CREATE TABLE title_catalog(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,created_by text REFERENCES "user"(id),created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE character_titles(character_id uuid NOT NULL REFERENCES characters(id),title_id uuid NOT NULL REFERENCES title_catalog(id),source text NOT NULL CHECK(source IN ('manual','automatic')),granted_by text REFERENCES "user"(id),granted_at timestamptz NOT NULL DEFAULT now(),revoked boolean NOT NULL DEFAULT false,PRIMARY KEY(character_id,title_id));
CREATE TABLE character_title_log(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,character_id uuid NOT NULL REFERENCES characters(id),title_id uuid NOT NULL REFERENCES title_catalog(id),action text NOT NULL CHECK(action IN ('grant','revoke','automatic')),actor_id text REFERENCES "user"(id),created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE characters ADD COLUMN displayed_title_id uuid REFERENCES title_catalog(id);
